import unittest
from slug import clean, slug
class Tests(unittest.TestCase):
    def test_existing(self):
        self.assertEqual(clean(" A  B "),"a b")
        self.assertEqual(clean(" "),"n-a")

    def test_slug_spaces(self):
        self.assertEqual(slug(" A  B\tC\nD "), "a-b-c-d")

    def test_slug_empty(self):
        for text in ("", " \t\n"):
            with self.subTest(text=text):
                self.assertEqual(slug(text), "n-a")

    def test_slug_unicode(self):
        self.assertEqual(slug(" CAFÉ\u2003Straße 東京 "), "café-strasse-東京")

