import unittest
from unittest.mock import patch
from slug import clean, slug
class Tests(unittest.TestCase):
    def test_existing(self):
        self.assertEqual(clean(" A  B "),"a b")
        self.assertEqual(clean(" "),"n-a")

    def test_slug_normalizes_whitespace_and_case(self):
        self.assertEqual(slug(" A\t B\n C "), "a-b-c")

    def test_slug_empty_fallback(self):
        self.assertEqual(slug(""), "n-a")
        self.assertEqual(slug(" \t\n"), "n-a")

    def test_slug_preserves_unicode(self):
        self.assertEqual(slug(" CAFÉ 東京 Straße "), "café-東京-strasse")

    def test_slug_reuses_clean(self):
        with patch("slug.clean", return_value="normalized text") as normalize:
            self.assertEqual(slug("original"), "normalized-text")
            normalize.assert_called_once_with("original")

